package com.example.acres.entity;
import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="users", indexes=@Index(name="idx_users_email", columnList="email")) @Getter @Setter @NoArgsConstructor
public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String name; @Column(nullable=false,unique=true) private String email; @Column(nullable=false) private String passwordHash; @Enumerated(EnumType.STRING) @Column(nullable=false) private Role role=Role.USER; @Column(nullable=false) private boolean active=true; @Column(nullable=false) private boolean mustChangePassword=false; @Column(name="token_version",nullable=false) private long tokenVersion=0; @Column(nullable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; private Instant lastLoginAt; @PrePersist void pre(){createdAt=updatedAt=Instant.now();} @PreUpdate void upd(){updatedAt=Instant.now();} }
